import{_ as e,o as a,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-08-24","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-08-24","date":"2021-08-24T00:00:00.000Z","updated":"2021-08-25T00:00:00.000Z","tags":["Ceph","Orchestrator","Integration Testing","Async SSH","Cephadm"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-24.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-08-24.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-08-24.md"};function o(n,l,s,h,u,c){return a(),t("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议为每周一次的Ceph Orchestrator会议，主要内容包括两个项目的更新报告。会议由主持人开场，随后分别由Aaron和Melissa进行项目进展的展示。</p><h4 id="第一个项目-aaron的周二项目更新" tabindex="-1">第一个项目：Aaron的周二项目更新 <a class="header-anchor" href="#第一个项目-aaron的周二项目更新" aria-label="Permalink to &quot;第一个项目：Aaron的周二项目更新&quot;">​</a></h4><ul><li><strong>项目背景</strong>：Aaron介绍了他在过去几个月中致力于开发一个新的集成测试框架，使用Jacqueline语言来确保Orchestrator操作的安全性。</li><li><strong>技术细节</strong>： <ul><li><strong>Jacqueline语言</strong>：一种使用常见关键词（如Given、And、Then）定义执行步骤的自然语言，用于创建测试场景。</li><li><strong>KCLI工具</strong>：用于创建运行特定测试的环境。</li><li><strong>项目目标</strong>：创建类似执行命令并验证命令输出的场景，无需编程语言知识。</li></ul></li><li><strong>当前进展</strong>： <ul><li>实现了用户定义不同测试实验室配置的功能，使用KCLI创建环境并执行特定测试。</li><li>用户可以定义在虚拟机上执行的命令，并指定预期输出中的关键词。</li><li>正在进一步定义更多测试场景，并实现命令执行和输出存储的功能。</li></ul></li><li><strong>实施结构</strong>： <ul><li>使用Behave测试框架，定义在.feature文件中，步骤实现则在Python脚本中。</li><li>环境配置示例：三个节点，每个节点4GB RAM和4个CPU，使用Fedora 32镜像。</li></ul></li><li><strong>当前问题</strong>： <ul><li>无法使用Talks命令运行Behave测试，因为需要环境变量和适当权限。</li><li>正在寻找解决方案以缓解此问题。</li></ul></li></ul><h4 id="第二个项目-melissa的outreach实习项目更新" tabindex="-1">第二个项目：Melissa的Outreach实习项目更新 <a class="header-anchor" href="#第二个项目-melissa的outreach实习项目更新" aria-label="Permalink to &quot;第二个项目：Melissa的Outreach实习项目更新&quot;">​</a></h4><ul><li><strong>项目背景</strong>：Melissa的项目旨在用Python的Async SSH库替换Zeknet和Remoto，以改善Cephadm中的远程命令执行。</li><li><strong>技术细节</strong>： <ul><li><strong>Async SSH</strong>：一个异步实现的SSH协议库，支持OpenSSH配置，提供更好的错误处理和调试日志。</li><li><strong>挑战</strong>： <ul><li>选择合适的Python SSH库。</li><li>将异步函数集成到现有的同步代码中。</li><li>学习和调试容器化环境。</li></ul></li></ul></li><li><strong>实施结构</strong>： <ul><li>创建一个专用的SSH线程，并在该线程中运行事件循环。</li><li>使用同步包装函数来调用异步协程，确保代码的同步执行顺序。</li><li>示例代码展示了如何使用Async SSH执行远程命令并处理结果。</li></ul></li><li><strong>未来展望</strong>： <ul><li>确保有一个专用的SSH线程和线程安全的异步函数调用。</li><li>开发者可以继续使用同步包装函数，无需过多关注事件循环。</li></ul></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>Aaron的项目</strong>： <ul><li>继续定义和实现更多的测试场景。</li><li>寻找并实施解决方案以解决Behave测试的权限问题。</li></ul></li><li><strong>Melissa的项目</strong>： <ul><li>确保Async SSH的稳定集成和维护。</li><li>考虑将Async SSH库添加到Ceph的依赖管理中，特别是对于CentOS等系统。</li></ul></li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了Async编程在Cephadm中的应用和潜在影响。</li><li>提出了关于依赖管理和库选择的未来工作方向。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后圆满结束，感谢所有参与者的贡献和讨论。</p>',13)])])}const p=e(r,[["render",o]]);export{g as __pageData,p as default};
